// Build the npm release asset from an exact committed revision, offline, in a container running
// as uid 19001. The host writes the committed tree with git archive to a group-readable file
// outside the checkout, bound read-only (--group-add its group); the npm cache comes read-only
// from a prepared check image or the legacy volume; the host user copies artifacts with docker cp.
// Output: delivery-kit-VERSION.tgz, SOURCE_COMMIT and SHA256SUMS.
// Usage: pack.ts EXACT_COMMIT_SHA NEW_ABSOLUTE_DIRECTORY
import { spawnSync } from "node:child_process";
import { chmodSync, lstatSync, mkdirSync, mkdtempSync, realpathSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, isAbsolute, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import {
  checkImage,
  CONTAINER_ID,
  DEFAULT_VOLUME,
  groupAdds,
  GuardError,
  run,
  validPackArgs,
} from "./guards.ts";

const USAGE = "usage: npm run pack -- EXACT_COMMIT_SHA NEW_ABSOLUTE_DIRECTORY";

const PACK = `
  umask 022
  mkdir /tmp/package /tmp/out
  tar -x -f /source.tar -C /tmp/package
  cd /tmp/package
  printf "%s\\n" "$SOURCE_REVISION" >SOURCE_COMMIT
  if [ -n "\${PACK_STOCK_IMAGE:-}" ]; then
    node /stock-cache.ts /stock-dependencies.tar /tmp/package "$PACK_STOCK_IMAGE"
  else
    cp -R "$PACK_NPM_CACHE" /tmp/npm-cache
  fi
  npm ci --offline --ignore-scripts --no-audit --no-fund
  node scripts/build.mjs
  node scripts/release-package.mjs /tmp/release /tmp/out
`;

function capture(command: string, args: readonly string[]): string {
  const result = spawnSync(command, args, { encoding: "utf8" });
  if (result.status !== 0) {
    throw new GuardError(`${command} ${args.join(" ")} failed`);
  }
  return result.stdout.trim();
}

function quiet(command: string, args: readonly string[]): number {
  return spawnSync(command, args, { stdio: "ignore" }).status ?? 1;
}

function main(args: string[]): number {
  process.umask(0o022);
  const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
  if (!validPackArgs(args)) {
    console.error(USAGE);
    return 2;
  }
  const [sha, outputArg] = args as [string, string];
  const revision = spawnSync("git", ["-C", root, "rev-parse", "--verify", `${sha}^{commit}`], {
    encoding: "utf8",
  });
  if (revision.status !== 0 || revision.stdout.trim() !== sha) {
    return 2;
  }
  const volume = process.env.DELIVERY_KIT_NPM_VOLUME ?? DEFAULT_VOLUME;
  const prepared = process.env.CONTAINER_IMAGE;
  let image: string;
  let cacheMount: string[];
  let cachePath: string;
  const stock = process.env.DELIVERY_KIT_STOCK_CACHE;
  let stockImage: string | undefined;
  if (stock !== undefined) {
    if (!isAbsolute(stock) || !lstatSync(stock).isFile() || lstatSync(stock).isSymbolicLink()) {
      throw new GuardError("DELIVERY_KIT_STOCK_CACHE must be an absolute regular archive");
    }
    const validated = spawnSync(
      "bash",
      [
        "-eu",
        "-c",
        'source "$1"; stock_validate_dependencies "$2"',
        "stock-cache",
        join(root, "tests/container/stock"),
        stock,
      ],
      { stdio: ["ignore", "ignore", "inherit"] },
    );
    if (validated.status !== 0) throw new GuardError("invalid canonical stock cache archive");
    const pinned = capture("docker", ["image", "inspect", "--format", "{{.Id}}", checkImage(root)]);
    image = capture("docker", [
      "image",
      "inspect",
      "--format",
      "{{.Id}}",
      prepared ?? checkImage(root),
    ]);
    if (!/^sha256:[0-9a-f]{64}$/.test(image) || pinned !== image)
      throw new GuardError("stock cache requires the actual pinned Node image");
    stockImage = image;
    cacheMount = [
      "--mount",
      `type=bind,src=${stock},dst=/stock-dependencies.tar,readonly`,
      "--mount",
      `type=bind,src=${join(root, "scripts/stock-cache.ts")},dst=/stock-cache.ts,readonly`,
    ];
    cachePath = "/tmp/npm-cache";
  } else if (prepared !== undefined) {
    if (!/^[A-Za-z0-9][A-Za-z0-9._/:@-]*$/.test(prepared)) {
      console.error("delivery-kit: CONTAINER_IMAGE must identify a prepared check image");
      return 2;
    }
    const inspected = spawnSync("docker", ["image", "inspect", "--format", "{{.Id}}", prepared], {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    });
    image = inspected.stdout?.trim() ?? "";
    if (inspected.status !== 0 || !/^sha256:[0-9a-f]{64}$/.test(image)) {
      console.error(
        "delivery-kit: prepared CONTAINER_IMAGE unavailable; run make check with that image first",
      );
      return 2;
    }
    cacheMount = [];
    cachePath = "/opt/check/npm-cache";
  } else {
    if (quiet("docker", ["volume", "inspect", volume]) !== 0) {
      console.error(
        `delivery-kit: prepare cache volume ${volume} or use a prepared CONTAINER_IMAGE`,
      );
      return 2;
    }
    image = checkImage(root);
    cacheMount = ["--mount", `type=volume,src=${volume},dst=/var/tmp,readonly`];
    cachePath = "/var/tmp/npm";
  }

  // Deterministic per revision, so a leftover container from an interrupted pack is replaced.
  const name = `delivery-kit-pack-${sha.slice(0, 12)}`;
  quiet("docker", ["rm", "--force", name]);
  const scratch = mkdtempSync(join(tmpdir(), "delivery-kit-pack-"));
  const archive = join(scratch, "source.tar");
  try {
    capture("git", ["-C", root, "archive", "-o", archive, sha]);
    chmodSync(archive, 0o640);
    const epoch = capture("git", ["-C", root, "show", "-s", "--format=%ct", sha]);
    const created = spawnSync(
      "docker",
      [
        "create",
        "--name",
        name,
        "--network",
        "none",
        "--cpus",
        "4",
        "--memory",
        "4g",
        "--ulimit",
        "nofile=256:256",
        "--user",
        `${CONTAINER_ID}:${CONTAINER_ID}`,
        "-e",
        "HOME=/tmp",
        ...groupAdds(
          stock === undefined ? [archive] : [archive, stock, join(root, "scripts/stock-cache.ts")],
        ),
        "--mount",
        `type=bind,src=${archive},dst=/source.tar,readonly`,
        ...cacheMount,
        "-e",
        `SOURCE_DATE_EPOCH=${epoch}`,
        "-e",
        `SOURCE_REVISION=${sha}`,
        "-e",
        `PACK_NPM_CACHE=${cachePath}`,
        ...(stockImage === undefined ? [] : ["-e", `PACK_STOCK_IMAGE=${stockImage}`]),
        "-e",
        "npm_config_cache=/tmp/npm-cache",
        "-w",
        "/tmp",
        image,
        "sh",
        "-ec",
        PACK,
      ],
      { stdio: ["ignore", "ignore", "inherit"] },
    );
    if (created.status !== 0) {
      return created.status ?? 1;
    }
    const started = run("docker", ["start", "-a", name]);
    if (started !== 0) {
      return started;
    }
    mkdirSync(outputArg, { recursive: true });
    const output = realpathSync(outputArg);
    const copied = run("docker", ["cp", "--quiet", `${name}:/tmp/out/.`, `${output}/`]);
    if (copied !== 0) {
      return copied;
    }
    console.log(`delivery-kit: release artifacts in ${output}`);
    return 0;
  } finally {
    quiet("docker", ["rm", "--force", name]);
    rmSync(scratch, { force: true, recursive: true });
  }
}

try {
  process.exitCode = main(process.argv.slice(2));
} catch (error) {
  console.error(`delivery-kit: ${error instanceof GuardError ? error.message : String(error)}`);
  process.exitCode = 1;
}

