        .update(readFileSync(join(root, path)))
        .digest("hex"),
    ]),
  );
}

export function dependencyProfile(root: string, imageId: string) {
  if (!/^sha256:[a-f0-9]{64}$/.test(imageId))
    throw new Error("stock cache requires an immutable image ID");
  return {
    version: 1,
    kind: "delivery-kit-node-dependencies",
    imageId,
    nodeVersion: process.version,
    cacheMember: CACHE_MEMBER,
    inputs: inputHashes(root),
  };
}

export function validateProfile(value: unknown, root: string, imageId: string): void {
  if (typeof value !== "object" || value === null || Array.isArray(value))
    throw new Error("malformed stock cache profile");
  const profile = value as Record<string, unknown>;
  if (
    profile.version !== 1 ||
    profile.kind !== "delivery-kit-node-dependencies" ||
    profile.cacheMember !== CACHE_MEMBER
  )
    throw new Error("unsupported stock cache profile");
  if (!/^sha256:[a-f0-9]{64}$/.test(imageId) || profile.imageId !== imageId)
    throw new Error("stock cache image binding mismatch");
  if (
    profile.nodeVersion !== process.version ||
    process.version !== readFileSync(join(root, ".nvmrc"), "utf8").trim()
  )
    throw new Error("stock cache Node version mismatch");
  if (JSON.stringify(profile.inputs) !== JSON.stringify(inputHashes(root)))
    throw new Error("stock cache frozen inputs mismatch");
}

function regularTree(path: string): void {
  const stat = lstatSync(path);
  if (stat.isDirectory()) for (const name of readdirSync(path)) regularTree(join(path, name));
  else if (!stat.isFile())
    throw new Error("stock npm cache must contain only regular files and directories");
}

/** Called only inside the disposable pack container after canonical header validation. */
export function restoreStockCache(
  archive: string,
  root: string,
  imageId: string,
  destination: string,
): void {
  const profile = execFileSync("tar", ["-xOf", archive, "scratch/node/profile.json"], {
    encoding: "utf8",
    maxBuffer: 65536,
  });
  validateProfile(JSON.parse(profile), root, imageId);
  const staging = join(destination, "stock-input");
  mkdirSync(staging);
  execFileSync("tar", ["-xf", archive, "-C", staging, "--no-same-owner", CACHE_MEMBER]);
  const cache = join(staging, CACHE_MEMBER);
  regularTree(cache);
  if (!lstatSync(cache).isDirectory()) throw new Error("stock npm cache directory missing");
  const target = join(destination, "npm-cache");
  mkdirSync(target);
  cpSync(cache, join(target, "_cacache"), { recursive: true });
}

if (process.argv[1] !== undefined && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const [archive, root, image] = process.argv.slice(2);
    if (
      process.argv.length !== 5 ||
      archive === undefined ||
      root === undefined ||
      image === undefined
    )
      throw new Error("stock cache requires archive, source and image ID");
    restoreStockCache(archive, root, image, "/tmp");
  } catch (error) {
    console.error(String(error));
    process.exitCode = 1;
  }
}

