import { execFileSync, spawnSync } from "node:child_process";
import { copyFileSync, mkdirSync, symlinkSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { build, lintNode, markdown, test } from "./check.ts";
import { dependencyProfile } from "./stock-cache.ts";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const base = "/scratch/node";

function main(action: string | undefined, args: readonly string[]): void {
  if (action === "prepare") {
    if (args.length !== 1 || args[0] === undefined)
      throw new Error("prepare requires the immutable Node image ID");
    const profile = dependencyProfile(root, args[0]);
    for (const relative of ["", "tests/contract"]) {
      const source = join(root, relative);
      const target = join(base, relative === "" ? "root" : "contract");
      mkdirSync(target, { recursive: true });
      for (const name of ["package.json", "package-lock.json"])
        copyFileSync(join(source, name), join(target, name));
      const result = spawnSync(
        "npm",
        ["ci", "--prefix", target, "--ignore-scripts", "--no-audit", "--no-fund", "--maxsockets=1"],
        {
          env: { ...process.env, npm_config_cache: join(base, "npm-cache") },
          stdio: ["ignore", 2, 2],
        },
      );
      if (result.status !== 0)
        throw new Error("locked dependency installation failed: " + String(result.status));
    }
    writeFileSync(join(base, "profile.json"), JSON.stringify(profile));
    execFileSync("tar", ["-cf", "-", "-C", "/", "scratch/node"], { stdio: ["ignore", 1, 2] });
    return;
  }
  symlinkSync(join(base, "root/node_modules"), join(root, "node_modules"));
  symlinkSync(join(base, "contract/node_modules"), join(root, "tests/contract/node_modules"));
  if (action === "test") test(root, args);
  else if (args.length !== 0) throw new Error("unexpected profile arguments");
  else if (action === "lint") lintNode(root);
  else if (action === "markdown") markdown(root);
  else if (action === "build") build(root);
  else throw new Error("unknown stock profile action");
}

try {
  main(process.argv[2], process.argv.slice(3));
} catch (error) {
  console.error("stock-profile: " + String(error));
  process.exitCode = 1;
}

