  "private": true,
  "config": {
    "VERSION": "v1"
  },
  "dependencies": {
    "ergogen": "^4.2.1"
  },
  "devDependencies": {
    "@eslint/js": "^10.0.1",
    "eslint": "^10.13.0",
    "eslint-plugin-simple-import-sort": "^14.0.0",
    "eslint-plugin-sort-destructure-keys": "^3.0.0",
    "globals": "^17.13.0",
    "husky": "^9.1.7",
    "lint-staged": "^17.6.0",
    "nodemon": "^3.1.14",
    "prettier": "^3.9.10",
    "markdownlint-cli2": "0.24.0"
  },
  "engines": {
    "node": ">=24.22.2"
  },
  "scripts": {
    "build": "sh -c 'set -vxe;npx ergogen ./${npm_package_config_VERSION}/ergogen/ --output dist/${npm_package_config_VERSION}/ergogen/ && npm run update-pcbs'",
    "clean": "rm -rf dist",
    "copy-pcbs-to-kicad": "sh -c 'set -vxe;cp dist/${npm_package_config_VERSION}/ergogen/pcbs/[!_]*.kicad_pcb ./${npm_package_config_VERSION}/kicad/'",
    "copy-pcbs-to-routed": "sh -c 'set -vxe;cp ./${npm_package_config_VERSION}/kicad/[!_]*.kicad_pcb ./${npm_package_config_VERSION}/kicad/routed/'",
    "copy-traces-from-routed": "sh -c 'set -vxe;for f in ./${npm_package_config_VERSION}/kicad/routed/[!_]*.kicad_pcb; do echo \"${f}\" && python3 ./${npm_package_config_VERSION}/ergogen/kb_ergogen_helper/ergogen_helper.py --no-backup copy-traces \"${f}\" ./${npm_package_config_VERSION}/kicad/$(basename \"${f}\"); done'",
    "fab-jlcpcb": "sh -c 'set -vxe;for f in ./${npm_package_config_VERSION}/kicad/routed/[!_]*.kicad_pcb; do echo \"${f}\" && kikit fab jlcpcb --nametemplate \"ha-harmony-remote_{boardTitle}_{date}\" \"${f}\" dist/${npm_package_config_VERSION}/kicad/jlcpcb/; done'",
    "format": "prettier --write . && eslint --fix .",
    "lint": "prettier --check . && eslint --max-warnings 0 .",
    "prepare": "husky",
    "update-pcbs": "sh -c 'set -vxe;for f in dist/${npm_package_config_VERSION}/ergogen/pcbs/[!_]*.kicad_pcb; do echo ${f} && python3 ./${npm_package_config_VERSION}/ergogen/kb_ergogen_helper/ergogen_helper.py --no-backup update-pcb ${f}; done'",
    "watch": "sh -c 'set -vxe;nodemon --ext .js,.yaml --watch ./${npm_package_config_VERSION}/ergogen/config.yaml --exec \"npm run build\"'",
    "watch-and-copy-pcbs-to-kicad": "sh -c 'set -vxe;nodemon --ext .js,.yaml --watch ./${npm_package_config_VERSION}/ergogen/config.yaml --exec \"npm run build && npm run copy-pcbs-to-kicad\"'"
  },
  "overrides": {
    "markdownlint-cli2@0.24.0": {
      "markdownlint": "0.42.1",
      "katex": "0.19.1"
    }
  }
}

blobs.e058c84b8b881739b6c9370cbe40765f2073f278:
"""Validate YAML syntax and duplicate keys without resolving application tags."""

from pathlib import Path

import yaml


class Loader(yaml.SafeLoader):
    pass


def mapping(loader, node, deep=False):
    seen, result = set(), {}
    for key_node, value_node in node.value:
        key = loader.construct_object(key_node, deep=deep)
        if key in seen:
            raise SystemExit(f"{path}:{key_node.start_mark.line + 1}: duplicate key {key!r}")
        seen.add(key)
        result[key] = loader.construct_object(value_node, deep=deep)
    return result


Loader.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG, mapping)
Loader.add_multi_constructor("", lambda loader, suffix, node: None)

excluded = (".github", "ergogen/footprints", "ergogen/kb_ergogen_helper")
paths = sorted(
    path
    for path in Path(".").rglob("*")
    if path.suffix in (".yaml", ".yml")
    and not any(path.as_posix().startswith(prefix + "/") for prefix in excluded)
)
if not paths:
    raise SystemExit("No YAML files matched: the gate checked nothing")
for path in paths:
    print(path)
    with path.open(encoding="utf-8") as source:
        yaml.load(source, Loader=Loader)

